  "a_sentences": [
    {
      "a_text": "Das kantonale Gericht legte die Bestimmungen und Grundsätze zu den am 1. Januar 2022 revidierten Bestimmungen im IVG, zur Invalidität (Art. 8 Abs. 1 ATSG), zur Erwerbsunfähigkeit (Art. 7 ATSG) und zum Rentenanspruch (Art. 28 IVG) richtig dar.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Gleiches gilt in Bezug auf die Bemessung der Invalidität nach der allgemeinen Methode des Einkommensvergleichs (Art. 16 ATSG).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Nichts zu ihren Gunsten abzuleiten vermag die Versicherte auch aus ihrem Einwand betreffend die vom Bundesgericht frei überprüfbare Rechtsfrage zur Gewährung eines Leidensabzugs.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Das Bundesgericht erachtete die gutachterliche Einschätzung einer 80%igen Arbeitsfähigkeit in angepassten Tätigkeiten ab Sommer 2022 als beweiskräftig.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Insbesondere ist keine Rechtsverletzung im Sinn eines Ermessensmissbrauchs bzw. einer -unterschreitung ersichtlich.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Nach dem Ausgeführten hat die Vorinstanz kein Bundesrecht verletzt, indem sie den Rentenanspruch der Versicherten verneinte.",
      "b_propositions": ["P6"]
    }
  ]
}
